// The visitor's hand in Yui's touch mode: a smooth, skinned toon hand (`models/hand.glb`, generated by
// `tools/assets/build_hand.py`) with a thin ink outline and a short grey-blue cuff. It follows the pointer, takes a
// pose for the part of her it is over, and rests on her while held. Local frame: palm at the origin, fingers along
// +z, the back of the hand +y, the thumb at -x.
import * as T from "./engine/three.module.min.js"
import { GLTFLoader } from "./engine/three-gltf.mjs?v=0.9.29"

// Curl of each finger's three joints (index, middle, ring, little), and the thumb's turn toward the palm and bend.
const POSES = {
  relax: { fingers: [[.28, .3, .2], [.34, .34, .22], [.4, .36, .24], [.48, .38, .26]], thumb: [.2, .15] },
  pat: { fingers: [[.12, .12, .08], [.11, .12, .08], [.14, .13, .09], [.18, .15, .1]], thumb: [.05, .05] },
  poke: { fingers: [[0, .02, 0], [1.45, 1.6, 1.1], [1.5, 1.6, 1.1], [1.5, 1.55, 1.05]], thumb: [1.05, .85] },
  hold: { fingers: [[.3, .26, .16], [.3, .26, .16], [.33, .27, .17], [.38, .3, .2]], thumb: [.3, .15] },
  pinch: { fingers: [[.65, .55, .3], [.6, .5, .3], [1.1, 1.2, .9], [1.2, 1.2, .9]], thumb: [.6, .35] },
  // Fingertips bent up under her chin; they scratch while the touch is held (see scratching).
  scratch: { fingers: [[.55, .7, .45], [.5, .7, .45], [.55, .7, .45], [.7, .75, .5]], thumb: [.15, .1] },
}
// Which pose for which part of her, and the point of the hand that touches.
export const HAND_POSE = { head: "pat", cheek: "poke", chin: "scratch", hand: "hold", ears: "pinch", tail: "hold", none: "relax" }
const FINGERS = ["index", "middle", "ring", "little"]
// Length of each fingertip segment and its radius, as built (for the nails).
const TIPS = { index: [.0115, .0080], middle: [.012, .0083], ring: [.0115, .0078], little: [.0098, .0068] }
const INK = .0013

// A drawn outline: the back faces of a copy pushed out along the normals (before skinning, so it bends along).
function ink(color) {
  const material = new T.MeshBasicMaterial({ color, side: T.BackSide })
  material.onBeforeCompile = shader => {
    shader.vertexShader = shader.vertexShader.replace("#include <begin_vertex>",
      `#include <begin_vertex>\n transformed += normalize(normal) * ${INK.toFixed(4)};`)
  }
  return material
}

export function createHand(scene, base = "./models") {
  const ramp = new T.DataTexture(new Uint8Array([176, 230, 255]), 3, 1, T.RedFormat)
  ramp.minFilter = ramp.magFilter = T.NearestFilter
  ramp.needsUpdate = true
  // Like Yui, part of the colour is self-lit, dimmed with the room light by the caller.
  const toon = (color, glow) => {
    const material = new T.MeshToonMaterial({ color, gradientMap: ramp, emissive: color, emissiveIntensity: glow })
    material.userData.glow = glow
    return material
  }
  const skin = toon(0xf7d9cc, .42)
  const cuff = toon(0xa9bccf, .32)
  const nail = toon(0xfde9e4, .5)
  // The far end of the cuff is its opening, a shade darker so it does not read as a lid.
  const opening = toon(0x6f8194, .2)
  const materials = [skin, cuff, nail, opening]
  const skinLine = ink(0x9a6658)
  const clothLine = ink(0x4e5d6d)

  const hand = new T.Group()
  hand.visible = false
  const sleeve = new T.Mesh(new T.CylinderGeometry(.032, .035, .04, 24), [cuff, cuff, opening])
  sleeve.rotation.x = Math.PI / 2
  sleeve.position.z = -.064
  sleeve.add(new T.Mesh(sleeve.geometry, clothLine))
  hand.add(sleeve)
  const band = new T.Mesh(new T.TorusGeometry(.033, .0045, 10, 28), cuff)
  band.position.z = -.044
  hand.add(band)
  scene.add(hand)

  // Each joint turns about an axis fixed in the hand (fingers curl about +x, toward the palm); the axes are found
  // in each bone's own frame once the model has loaded.
  const joints = []
  const thumbJoints = []
  const pokeTip = new T.Vector3(-.027, 0, .088)
  const ready = new GLTFLoader().loadAsync(`${base}/hand.glb?v=0.9.37`).then(gltf => {
    const model = gltf.scene
    model.updateMatrixWorld(true)
    const bone = name => model.getObjectByName(name)
    const frame = new T.Quaternion()
    const axisIn = (object, axis) => axis.clone().applyQuaternion(object.getWorldQuaternion(frame).invert()).normalize()
    const curl = new T.Vector3(1, 0, 0)
    for (const name of FINGERS) {
      joints.push([1, 2, 3].map(i => {
        const object = bone(`${name}_${i}`)
        return { object, rest: object.quaternion.clone(), axis: axisIn(object, curl) }
      }))
      // A nail on the back of each fingertip, on the fingertip bone.
      const [length, radius] = TIPS[name]
      const tipBone = bone(`${name}_3`)
      const from = bone(`${name}_2`).getWorldPosition(new T.Vector3())
      const at = tipBone.getWorldPosition(new T.Vector3())
      const along = at.clone().sub(from).normalize()
      const shell = new T.Mesh(new T.SphereGeometry(1, 14, 10), nail)
      shell.scale.set(radius * .62, radius * .2, length * .42)
      shell.position.copy(at).addScaledVector(along, length * .6).add(new T.Vector3(0, radius * .66, 0))
      shell.quaternion.setFromUnitVectors(new T.Vector3(0, 0, 1), along)
      model.add(shell)
      shell.updateMatrixWorld(true)
      tipBone.attach(shell)
      if (name === "index") pokeTip.copy(at).addScaledVector(along, length + radius * .5)
    }
    // The thumb turns in toward the palm and the index finger.
    const toward = new T.Vector3(1, -.45, .15).normalize()
    for (const i of [1, 2, 3]) {
      const object = bone(`thumb_${i}`)
      const start = object.getWorldPosition(new T.Vector3())
      const direction = i < 3 ? bone(`thumb_${i + 1}`).getWorldPosition(new T.Vector3()).sub(start).normalize()
        : thumbJoints[1].direction
      thumbJoints.push({ object, rest: object.quaternion.clone(), direction,
        axis: axisIn(object, new T.Vector3().crossVectors(direction, toward).normalize()) })
    }
    model.traverse(object => {
      if (!object.isSkinnedMesh) return
      object.material = skin
      object.castShadow = false
      object.frustumCulled = false
      const line = new T.SkinnedMesh(object.geometry, skinLine)
      line.bind(object.skeleton, object.bindMatrix)
      line.frustumCulled = false
      object.parent.add(line)
      line.position.copy(object.position)
      line.quaternion.copy(object.quaternion)
      line.scale.copy(object.scale)
    })
    hand.add(model)
  }).catch(error => console.warn("cottage hand", error))

  // Current joint angles ease toward the pose; position and turn ease toward the goal.
  const angles = FINGERS.map(() => [0, 0, 0])
  const thumb = [0, 0]
  let pose = "relax"
  const goal = { position: new T.Vector3(), quaternion: new T.Quaternion() }
  const damp = (value, target, rate, dt) => value + (target - value) * (1 - Math.exp(-rate * dt))
  const contact = new T.Vector3()
  const basis = new T.Matrix4()
  const along = new T.Vector3()
  const back = new T.Vector3()
  const across = new T.Vector3()
  const turn = new T.Quaternion()
  let placed = false
  // While scratching, the three middle fingertips go back and forth.
  let scratching = false
  let scratchTime = 0
  const bend = (joint, angle) => joint.object.quaternion.copy(joint.rest).multiply(turn.setFromAxisAngle(joint.axis, angle))

  return {
    object: hand,
    ready,
    get pose() { return pose },
    setPose(name) { if (POSES[name]) pose = name },
    scratch(on) { scratching = Boolean(on) },
    show(visible) {
      hand.visible = visible
      if (!visible) placed = false
    },
    glow(amount) { for (const material of materials) material.emissiveIntensity = material.userData.glow * amount },
    // Points the fingers along `fingers` with the back of the hand toward `up`, and puts the touching point of the
    // current pose (palm, or index fingertip for a poke) at `point`.
    aim(point, fingers, up) {
      along.copy(fingers).normalize()
      across.crossVectors(up, along).normalize()
      back.crossVectors(along, across)
      basis.makeBasis(across, back, along)
      goal.quaternion.setFromRotationMatrix(basis)
      if (pose === "poke") contact.copy(pokeTip)
      else if (pose === "pinch") contact.set(-.03, -.012, .07)
      else if (pose === "scratch") contact.set(-.004, -.024, .066)
      else contact.set(0, -.012, .02)
      goal.position.copy(point).sub(contact.applyQuaternion(goal.quaternion))
    },
    // Returns true while it is still moving.
    update(dt, snap) {
      if (!hand.visible) return false
      const rate = 16
      const target = POSES[pose]
      let moving = false
      const ease = (value, wanted) => {
        const next = snap ? wanted : damp(value, wanted, rate, dt)
        if (Math.abs(next - wanted) > .002) moving = true
        return Math.abs(next - wanted) > .0005 ? next : wanted
      }
      const wiggle = pose === "scratch" && scratching && !snap
      scratchTime = wiggle ? scratchTime + dt : 0
      if (wiggle) moving = true
      angles.forEach((finger, i) => finger.forEach((angle, s) => {
        finger[s] = ease(angle, target.fingers[i][s])
        const scratchBy = wiggle && i < 3 && s < 2 ? Math.sin(scratchTime * 15 + i * .9) * (s ? .25 : .3) : 0
        if (joints[i]) bend(joints[i][s], finger[s] + scratchBy)
      }))
      thumb[0] = ease(thumb[0], target.thumb[0])
      thumb[1] = ease(thumb[1], target.thumb[1])
      if (thumbJoints.length) {
        bend(thumbJoints[0], thumb[0])
        bend(thumbJoints[1], thumb[1])
        bend(thumbJoints[2], thumb[1] * .8)
      }
      if (snap || !placed) {
        hand.position.copy(goal.position)
        hand.quaternion.copy(goal.quaternion)
        placed = true
      } else {
        const step = 1 - Math.exp(-22 * dt)
        hand.position.lerp(goal.position, step)
        hand.quaternion.slerp(goal.quaternion, step)
        if (hand.position.distanceToSquared(goal.position) > 1e-7) moving = true
      }
      return moving
    },
  }
}
